-- 完全合成的数据库测试样例，禁止冒充真实用户或真实到店记录。
-- 4个测试用户；3个示例点位；30打卡/7天；12条用户成就进度；3宠物/档案；5未完成任务。
-- 成就定义仍为3.0的4项，不新增12个定义。ID 8300001起为本包测试命名空间。
USE dafu_shike;
SET NAMES utf8mb4;
SET @db3_guard=IF(EXISTS(SELECT 1 FROM `user` WHERE id BETWEEN 8300001 AND 8300004 AND nickname NOT LIKE 'D合成测试用户%'), 'SELECT * FROM information_schema.D_DATA_NAMESPACE_COLLISION', 'DO 0');
PREPARE db3_stmt FROM @db3_guard;
EXECUTE db3_stmt;
DEALLOCATE PREPARE db3_stmt;
START TRANSACTION;
COMMIT;
